import pico from './vendor/pico.js';
import {samplingLayout} from './sampling.js';
import {modelSubject,subjectOptions} from './subject-model.js';
let classifier;
let detected=new WeakMap();
export function loadFaceModel(bytes){classifier=pico.unpack_cascade(new Int8Array(bytes));detected=new WeakMap();}
const lum=(r,g,b)=>r*.2126+g*.7152+b*.0722;
export function analysisRaster(source,max=320){const scale=Math.min(1,max/Math.max(source.width,source.height)),width=Math.max(1,Math.round(source.width*scale)),height=Math.max(1,Math.round(source.height*scale)),pixels=new Uint8Array(width*height*4);for(let y=0;y<height;y++)for(let x=0;x<width;x++){const i=(y*width+x)*4,s=(Math.min(source.height-1,Math.floor((y+.5)/height*source.height))*source.width+Math.min(source.width-1,Math.floor((x+.5)/width*source.width)))*4;pixels.set(source.pixels.slice(s,s+4),i);}return {width,height,pixels};}
function components(mask,w,h){const seen=new Uint8Array(mask.length),result=[];for(let i=0;i<mask.length;i++){if(!mask[i]||seen[i])continue;const points=[i];seen[i]=1;let x0=w,y0=h,x1=0,y1=0;for(let k=0;k<points.length;k++){const j=points[k],x=j%w,y=Math.floor(j/w);x0=Math.min(x0,x);y0=Math.min(y0,y);x1=Math.max(x1,x);y1=Math.max(y1,y);for(const v of [x?j-1:-1,x<w-1?j+1:-1,y?j-w:-1,y<h-1?j+w:-1])if(v>=0&&mask[v]&&!seen[v]){seen[v]=1;points.push(v);}}result.push({x:x0,y:y0,width:x1-x0+1,height:y1-y0+1,area:points.length,points});}return result.sort((a,b)=>b.area-a.area);}
function bounds(mask,w,h){let x=w,y=h,r=-1,b=-1,area=0;for(let i=0;i<mask.length;i++)if(mask[i]){area++;x=Math.min(x,i%w);y=Math.min(y,Math.floor(i/w));r=Math.max(r,i%w);b=Math.max(b,Math.floor(i/w));}return area?{x,y,width:r-x+1,height:b-y+1,area}:null;}
const rect=(x,y,width,height,w,h)=>{const left=Math.max(0,Math.floor(x)),top=Math.max(0,Math.floor(y)),right=Math.min(w,Math.ceil(x+width)),bottom=Math.min(h,Math.ceil(y+height));return {x:left,y:top,width:Math.max(1,right-left),height:Math.max(1,bottom-top)};};
function foreground(r){const {width:w,height:h,pixels:p}=r,n=w*h,alpha=Uint8Array.from({length:n},(_,i)=>p[i*4+3]>=128?1:0),opaque=alpha.reduce((a,b)=>a+b,0);if(!opaque)return {mask:alpha,method:'empty',reliability:'none'};if(opaque<n*.98)return {mask:alpha,method:'alpha',reliability:'high'};
 // Only flood colours represented on the image border; do not assume skin colour is foreground.
 const groups=new Map();for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(x===0||y===0||x===w-1||y===h-1){const i=(y*w+x)*4,key=(p[i]>>5)*64+(p[i+1]>>5)*8+(p[i+2]>>5),g=groups.get(key)??{n:0,sum:[0,0,0]};g.n++;for(let k=0;k<3;k++)g.sum[k]+=p[i+k];groups.set(key,g);}const border=2*w+2*h-4,palette=[...groups.values()].sort((a,b)=>b.n-a.n).filter(g=>g.n/border>=.06).slice(0,5).map(g=>g.sum.map(v=>v/g.n));
 const bg=new Uint8Array(n),queue=[];const near=i=>palette.some(c=>Math.hypot(p[i*4]-c[0],p[i*4+1]-c[1],p[i*4+2]-c[2])<48);for(let i=0;i<n;i++)if((i<w||i>=n-w||i%w===0||i%w===w-1)&&near(i)){bg[i]=1;queue.push(i);}for(let k=0;k<queue.length;k++){const i=queue[k],x=i%w;for(const j of [x?i-1:-1,x<w-1?i+1:-1,i-w,i+w])if(j>=0&&j<n&&!bg[j]&&near(j)){bg[j]=1;queue.push(j);}}
 const parts=components(Uint8Array.from(bg,v=>v?0:1),w,h),mask=new Uint8Array(n);for(const c of parts.filter(c=>c.area>=n*.015).slice(0,4))for(const i of c.points)mask[i]=1;const fraction=mask.reduce((a,b)=>a+b,0)/n;return {mask,method:'border-colour',reliability:fraction>.03&&fraction<.9?'review':'none'};
}
function featureBoxes(r,face,kind){const {width:w,height:h,pixels:p}=r,boxes=[],f=face;
 // Search within face-relative eye/mouth windows; report estimates, never biometric landmarks.
 for(const [name,rx,ry,rw,rh]of (kind==='photo'?[['left-eye',.2,.3,.26,.26],['right-eye',.54,.3,.26,.26],['mouth',.24,.7,.52,.24]]:[['left-eye',.08,.34,.36,.36],['right-eye',.5,.3,.36,.36],['mouth',.24,.66,.52,.26]])){const window=rect(f.x+rx*f.width,f.y+ry*f.height,rw*f.width,rh*f.height,w,h);let mean=0,count=0;for(let y=window.y;y<window.y+window.height;y++)for(let x=window.x;x<window.x+window.width;x++){const i=(y*w+x)*4;mean+=lum(...p.slice(i,i+3));count++;}mean/=count;let sx=0,sy=0,weight=0;for(let y=window.y;y<window.y+window.height;y++)for(let x=window.x;x<window.x+window.width;x++){const i=(y*w+x)*4,L=lum(...p.slice(i,i+3)),v=Math.max(0,mean-L-12);sx+=x*v;sy+=y*v;weight+=v;}const cx=weight?sx/weight:window.x+window.width/2,cy=weight?sy/weight:window.y+window.height/2,bw=f.width*(name==='mouth'?.42:.32),bh=f.height*(kind==='illustration'?.3:.24);boxes.push({name,method:weight?'local-contrast':'face-template',...rect(cx-bw/2,cy-bh/2,bw,bh,w,h)});}return boxes;
}
export function detectFocus(source,options={}){const {kind='auto'}=options,{subjectMode,subjectThreshold}=subjectOptions(options),cacheKey=kind+':'+subjectMode+':'+subjectThreshold;if(!['auto','photo','illustration'].includes(kind))throw Error('辨識類型需 auto/photo/illustration');const cached=detected.get(source)?.get(cacheKey);if(cached)return cached;const r=analysisRaster(source),{width:w,height:h,pixels:p}=r;let fg=foreground(r);const faces=[];
 if(classifier&&kind!=='illustration'){const gray=new Uint8Array(w*h);for(let i=0;i<gray.length;i++)gray[i]=p[i*4+3]<128?255:Math.round(lum(...p.slice(i*4,i*4+3)));const dets=pico.cluster_detections(pico.run_cascade({pixels:gray,nrows:h,ncols:w,ldim:w},classifier,{shiftfactor:.08,minsize:20,maxsize:Math.min(w,h)*.9,scalefactor:1.15}),.2);for(const [y,x,s,q]of dets.filter(d=>d[3]>20).slice(0,8))faces.push({...rect(x-s/2,y-s/2,s,s,w,h),method:'pico-face',score:Math.round(q)});}
 const colourCounts=new Map();let coloured=0;for(let i=0;i<w*h;i++)if(p[i*4+3]>=128){const key=(p[i*4]>>2)*4096+(p[i*4+1]>>2)*64+(p[i*4+2]>>2);colourCounts.set(key,(colourCounts.get(key)??0)+1);coloured++;}const flatShare=[...colourCounts.values()].sort((a,b)=>b-a).slice(0,32).reduce((a,b)=>a+b,0)/Math.max(1,coloured);
 if(!faces.length&&kind!=='photo'&&(kind==='illustration'||flatShare>.5)){
   const skin=new Uint8Array(w*h);for(let i=0;i<skin.length;i++){const [R,G,B,A]=p.slice(i*4,i*4+4);if(A>=128&&R>65&&R>G*1.03&&G>B*1.06&&R-B>18&&R-G<95&&fg.mask[i])skin[i]=1;}
   for(const c of components(skin,w,h).filter(c=>c.area>=w*h*.001&&c.width>=8&&c.height>=8&&c.width/c.height>.5&&c.width/c.height<1.3).slice(0,8)){const f=rect(c.x-c.width*.08,c.y-c.height*.14,c.width*1.16,c.height*1.25,w,h),features=featureBoxes(r,f,'illustration');let darkEyes=0;for(const b of features.slice(0,2)){let low=255,high=0;for(let y=b.y;y<b.y+b.height;y++)for(let x=b.x;x<b.x+b.width;x++){const i=(y*w+x)*4,L=lum(...p.slice(i,i+3));low=Math.min(low,L);high=Math.max(high,L);}if(high-low>55)darkEyes++;}if(darkEyes===2)faces.push({...f,method:'illustration-colour-contrast',score:null});}
 }
 const toSource=b=>rect(b.x/w*source.width,b.y/h*source.height,b.width/w*source.width,b.height/h*source.height,source.width,source.height),outFaces=faces.slice(0,4).map(f=>({bounds:toSource(f),method:f.method,score:f.score,features:featureBoxes(r,f,f.method==='pico-face'?'photo':'illustration').map(b=>({name:b.name,method:b.method,...toSource(b)}))}));
 if(subjectMode!=='fast'&&fg.method!=='alpha'&&fg.method!=='empty')fg=modelSubject(source,subjectThreshold,subjectMode);
 const mw=fg.width??w,mh=fg.height??h,b=bounds(fg.mask,mw,mh),subjectBounds=b?rect(b.x/mw*source.width,b.y/mh*source.height,b.width/mw*source.width,b.height/mh*source.height,source.width,source.height):null;
 const result={version:2,source:{width:source.width,height:source.height},analysis:{width:w,height:h},subject:{method:fg.method,reliability:fg.reliability,bounds:subjectBounds,coverage:b?Math.round(b.area/(mw*mh)*1000)/1000:0,...(['u2net','u2netp'].includes(fg.method)?{threshold:subjectThreshold,uncertainFraction:fg.uncertainFraction,inferenceMs:fg.inferenceMs}:{})},faces:outFaces,review:outFaces.length===0||outFaces.some(f=>f.method!=='pico-face')||fg.reliability!=='high',mask:fg.mask,maskWidth:mw,maskHeight:mh};const entries=detected.get(source)??new Map();entries.set(cacheKey,result);detected.set(source,entries);return result;
}
export function focusSummary(result){const {mask,maskWidth,maskHeight,...summary}=result;return summary;}
export function focusCrop(source,framing,kind='auto',options={}){if(!['face','subject','full'].includes(framing))throw Error('framing 需 full/face/subject');if(framing==='full')return undefined;const f=detectFocus(source,{...options,kind}),b=framing==='face'?f.faces[0]?.bounds:f.subject.bounds;if(!b)throw Error('找不到可用主體／人臉，請改用全圖或指定 crop');const margin=framing==='face'?{x:.3,y:.6,w:1.6,h:1.8}:{x:.05,y:.05,w:1.1,h:1.1};return rect(b.x-b.width*margin.x,b.y-b.height*margin.y,b.width*margin.w,b.height*margin.h,source.width,source.height);}
export function projectFocus(p,result){const layout=p.grid.output?samplingLayout(p.source,p.grid.output):{source:{x:p.grid.offsetX,y:p.grid.offsetY,width:p.width*p.grid.cellWidth,height:p.height*p.grid.cellHeight},content:{x:0,y:0,width:p.width,height:p.height}},s=layout.source,d=layout.content;
 const project=b=>{const x=d.x+(b.x-s.x)/s.width*d.width,y=d.y+(b.y-s.y)/s.height*d.height,right=d.x+(b.x+b.width-s.x)/s.width*d.width,bottom=d.y+(b.y+b.height-s.y)/s.height*d.height;if(right<=d.x||bottom<=d.y||x>=d.x+d.width||y>=d.y+d.height)return null;return rect(Math.max(d.x,x),Math.max(d.y,y),Math.min(right,d.x+d.width)-Math.max(d.x,x),Math.min(bottom,d.y+d.height)-Math.max(d.y,y),p.width,p.height);};
 const protect=result.faces.flatMap(f=>f.features.map(project).filter(Boolean));const mask=new Uint8Array(p.width*p.height);for(let y=d.y;y<d.y+d.height;y++)for(let x=d.x;x<d.x+d.width;x++){const sx=s.x+(x-d.x+.5)/d.width*s.width,sy=s.y+(y-d.y+.5)/d.height*s.height,xx=Math.floor(sx/p.source.width*result.maskWidth),yy=Math.floor(sy/p.source.height*result.maskHeight);if(xx>=0&&yy>=0&&xx<result.maskWidth&&yy<result.maskHeight)mask[y*p.width+x]=result.mask[yy*result.maskWidth+xx];}return {protect,mask,subjectBounds:result.subject.bounds?project(result.subject.bounds):null};
}
